((getMarkmap, getOptions, root2, jsonOptions) => {
              const markmap = getMarkmap();
              window.mm = markmap.Markmap.create(
                "svg#mindmap",
                (getOptions || markmap.deriveOptions)(jsonOptions),
                root2
              );
              if (window.matchMedia("(prefers-color-scheme: dark)").matches) {
                document.documentElement.classList.add("markmap-dark");
              }
            })(() => window.markmap,null,{"content":"📏 Crescimento Físico e Curvas de Crescimento da OMS","children":[{"content":"👤 Aluno","children":[{"content":"Nome: Paulo Alexandre Piornedo Panucci","children":[],"payload":{"tag":"li","lines":"3,4"}},{"content":"RA: 09057805","children":[],"payload":{"tag":"li","lines":"4,5"}},{"content":"Curso: Educação Física (Semipresencial)","children":[],"payload":{"tag":"li","lines":"5,6"}},{"content":"Matéria: Crescimento, Desenvolvimento e Aprendizagem Motora","children":[],"payload":{"tag":"li","lines":"6,7"}},{"content":"Polo: UNIPAR – Cianorte (PR)","children":[],"payload":{"tag":"li","lines":"7,9"}}],"payload":{"tag":"h2","lines":"2,3"}},{"content":"🧬 Conceito de Crescimento Físico","children":[{"content":"Definição","children":[{"content":"Aumento em tamanho e massa corporal ao longo do desenvolvimento","children":[],"payload":{"tag":"li","lines":"11,12"}},{"content":"Processo quantitativo e mensurável (Gallahue; Ozmun; Goodway, 2013)","children":[],"payload":{"tag":"li","lines":"12,13"}},{"content":"Inclui altura, peso e perímetros corporais","children":[],"payload":{"tag":"li","lines":"13,15"}}],"payload":{"tag":"h3","lines":"10,11"}},{"content":"Mecanismos celulares (Malina; Bouchard, 2002)","children":[{"content":"Hiperplasia – aumento do número de células por divisão celular","children":[],"payload":{"tag":"li","lines":"16,17"}},{"content":"Hipertrofia – aumento do volume das células","children":[],"payload":{"tag":"li","lines":"17,18"}},{"content":"Agregação – união de células para formação de tecidos e órgãos","children":[],"payload":{"tag":"li","lines":"18,20"}}],"payload":{"tag":"h3","lines":"15,16"}},{"content":"Fases do crescimento","children":[{"content":"Pré-natal: fecundação → zigoto → blástula → gastrulação → organogênese","children":[],"payload":{"tag":"li","lines":"21,22"}},{"content":"Neonatal: cabeça desproporcional, adaptação ao ambiente extrauterino","children":[],"payload":{"tag":"li","lines":"22,23"}},{"content":"Infância e adolescência: velocidade variável, pico puberal","children":[],"payload":{"tag":"li","lines":"23,25"}}],"payload":{"tag":"h3","lines":"20,21"}}],"payload":{"tag":"h2","lines":"9,10"}},{"content":"📊 Avaliação do Crescimento – Antropometria","children":[{"content":"O que é","children":[{"content":"Ciência das medidas e proporções do corpo humano","children":[],"payload":{"tag":"li","lines":"29,30"}},{"content":"Do grego anthropos (homem) + metron (medida)","children":[],"payload":{"tag":"li","lines":"30,32"}}],"payload":{"tag":"h3","lines":"28,29"}},{"content":"Principais medidas","children":[{"content":"Estatura – medida linear do topo da cabeça aos pés","children":[],"payload":{"tag":"li","lines":"33,34"}},{"content":"Peso – massa corporal total","children":[],"payload":{"tag":"li","lines":"34,35"}},{"content":"Envergadura – distância entre extremidades dos dedos médios","children":[],"payload":{"tag":"li","lines":"35,36"}},{"content":"IMC – peso (kg) ÷ altura² (m) → limitação: não distingue massa magra/gorda","children":[],"payload":{"tag":"li","lines":"36,37"}},{"content":"Circunferências – cintura, quadril, braço, coxa → risco cardiovascular (RCQ)","children":[],"payload":{"tag":"li","lines":"37,38"}},{"content":"Dobras cutâneas – estimativa de gordura subcutânea (adipômetro)","children":[],"payload":{"tag":"li","lines":"38,39"}},{"content":"Diâmetros ósseos – biacromial, bitrocantérico → somatotipos","children":[],"payload":{"tag":"li","lines":"39,41"}}],"payload":{"tag":"h3","lines":"32,33"}},{"content":"Protocolos","children":[{"content":"PROESP (Gaya et al., 2021): estatura, envergadura, peso para crianças 6–17 anos","children":[],"payload":{"tag":"li","lines":"42,43"}},{"content":"Uso de estadiômetro, fita métrica, balança, esquadro","children":[],"payload":{"tag":"li","lines":"43,45"}}],"payload":{"tag":"h3","lines":"41,42"}}],"payload":{"tag":"h2","lines":"27,28"}},{"content":"🌍 Curvas de Crescimento da OMS","children":[{"content":"Origem","children":[{"content":"Multicentre Growth Reference Study (MGRS) – 1997 a 2003","children":[],"payload":{"tag":"li","lines":"49,50"}},{"content":"6 países: Brasil, Gana, Índia, Noruega, Omã e EUA","children":[],"payload":{"tag":"li","lines":"50,51"}},{"content":"Objetivo: padrão prescritivo global baseado em crescimento ideal","children":[],"payload":{"tag":"li","lines":"51,52"}},{"content":"Aleitamento materno como modelo de referência (WHO, 2006)","children":[],"payload":{"tag":"li","lines":"52,54"}}],"payload":{"tag":"h3","lines":"48,49"}},{"content":"Parâmetros avaliados","children":[{"content":"Peso para a idade – adequação do peso à faixa etária","children":[],"payload":{"tag":"li","lines":"55,56"}},{"content":"Altura para a idade – verifica estatura esperada","children":[],"payload":{"tag":"li","lines":"56,57"}},{"content":"Peso para a altura – proporcionalidade peso × estatura","children":[],"payload":{"tag":"li","lines":"57,58"}},{"content":"IMC para a idade – estado nutricional","children":[],"payload":{"tag":"li","lines":"58,60"}}],"payload":{"tag":"h3","lines":"54,55"}},{"content":"Leitura e interpretação","children":[{"content":"Resultados plotados em percentis e escore z","children":[],"payload":{"tag":"li","lines":"61,62"}},{"content":"Entre –2 e +2 DP: zona de normalidade","children":[],"payload":{"tag":"li","lines":"62,63"}},{"content":"Abaixo de –2 DP ou acima de +2 DP → investigação necessária","children":[],"payload":{"tag":"li","lines":"63,64"}},{"content":"Curvas da OMS: 0–5 anos (growth standards) e referência 5–19 anos (2007)","children":[],"payload":{"tag":"li","lines":"64,66"}}],"payload":{"tag":"h3","lines":"60,61"}},{"content":"Aplicações práticas","children":[{"content":"Triagem nutricional em consultas pediátricas","children":[],"payload":{"tag":"li","lines":"67,68"}},{"content":"Vigilância de saúde pública","children":[],"payload":{"tag":"li","lines":"68,69"}},{"content":"Diagnóstico precoce: desnutrição, obesidade, nanismo, crescimento acelerado","children":[],"payload":{"tag":"li","lines":"69,70"}},{"content":"Acompanhamento por professores de Educação Física","children":[],"payload":{"tag":"li","lines":"70,72"}}],"payload":{"tag":"h3","lines":"66,67"}}],"payload":{"tag":"h2","lines":"47,48"}},{"content":"⚙️ Fatores que Influenciam o Crescimento","children":[{"content":"Genéticos","children":[{"content":"Definem o potencial máximo de crescimento","children":[],"payload":{"tag":"li","lines":"76,77"}},{"content":"Herança da estatura dos pais (estatura adulta predita – Roche, Wainer & Thissen, 1975)","children":[],"payload":{"tag":"li","lines":"77,79"}}],"payload":{"tag":"h3","lines":"75,76"}},{"content":"Hormonais","children":[{"content":"GH (Hormônio do Crescimento) – secretado pela hipófise; fundamental para crescimento ósseo e muscular","children":[],"payload":{"tag":"li","lines":"80,81"}},{"content":"Deficiência de GH: congênita, adquirida (lesão, tumor, infecção) ou idiopática","children":[],"payload":{"tag":"li","lines":"81,82"}},{"content":"Hormônios tireoidianos e gonadais na puberdade","children":[],"payload":{"tag":"li","lines":"82,84"}}],"payload":{"tag":"h3","lines":"79,80"}},{"content":"Nutricionais","children":[{"content":"Dieta equilibrada: carboidratos, proteínas, gorduras saudáveis, vitaminas e minerais","children":[],"payload":{"tag":"li","lines":"85,86"}},{"content":"Hidratação adequada","children":[],"payload":{"tag":"li","lines":"86,87"}},{"content":"Desnutrição → atraso no crescimento","children":[],"payload":{"tag":"li","lines":"87,88"}},{"content":"Obesidade infantil → puberdade precoce (Rios; Falcão; De Souza, 2023)","children":[],"payload":{"tag":"li","lines":"88,90"}}],"payload":{"tag":"h3","lines":"84,85"}},{"content":"Ambientais e socioeconômicos","children":[{"content":"Condições de saúde, acesso a saneamento, renda familiar","children":[],"payload":{"tag":"li","lines":"91,92"}},{"content":"Doenças crônicas (infecções gastrointestinais → má absorção de nutrientes)","children":[],"payload":{"tag":"li","lines":"92,94"}}],"payload":{"tag":"h3","lines":"90,91"}},{"content":"Exercício físico","children":[{"content":"Não altera diretamente a altura (Guedes, 1997)","children":[],"payload":{"tag":"li","lines":"95,96"}},{"content":"Aumenta diâmetro e mineralização óssea","children":[],"payload":{"tag":"li","lines":"96,97"}},{"content":"Favorece equilíbrio hormonal, circulação e imunidade","children":[],"payload":{"tag":"li","lines":"97,98"}},{"content":"Combate à obesidade","children":[],"payload":{"tag":"li","lines":"98,100"}}],"payload":{"tag":"h3","lines":"94,95"}}],"payload":{"tag":"h2","lines":"74,75"}},{"content":"🏃 Atividade Física e Desenvolvimento","children":[{"content":"Recomendações – Guia AF Brasil (2021)","children":[{"content":"Até 1 ano: ≥ 30 min/dia em posição de bruços","children":[],"payload":{"tag":"li","lines":"104,105"}},{"content":"1–2 anos: ≥ 3 h/dia de atividades de qualquer intensidade","children":[],"payload":{"tag":"li","lines":"105,106"}},{"content":"3–5 anos: ≥ 3 h/dia, sendo ≥ 1 h de intensidade moderada a vigorosa","children":[],"payload":{"tag":"li","lines":"106,107"}},{"content":"6–17 anos: ≥ 60 min/dia de intensidade moderada a vigorosa + ≥ 3x/semana fortalecimento muscular e ósseo","children":[],"payload":{"tag":"li","lines":"107,109"}}],"payload":{"tag":"h3","lines":"103,104"}},{"content":"Atividades indicadas (6–17 anos)","children":[{"content":"Esportes coletivos (futebol, basquete, vôlei, handebol)","children":[],"payload":{"tag":"li","lines":"110,111"}},{"content":"Brincadeiras ativas e jogos ao ar livre","children":[],"payload":{"tag":"li","lines":"111,112"}},{"content":"Deslocamento ativo (caminhar, pedalar)","children":[],"payload":{"tag":"li","lines":"112,113"}},{"content":"Exercícios com saltos, puxadas e empurrões (força)","children":[],"payload":{"tag":"li","lines":"113,115"}}],"payload":{"tag":"h3","lines":"109,110"}},{"content":"Locais de prática","children":[{"content":"Escolas (aulas de Educação Física)","children":[],"payload":{"tag":"li","lines":"116,117"}},{"content":"Parques e praças públicas","children":[],"payload":{"tag":"li","lines":"117,118"}},{"content":"Academias da Saúde (SUS)","children":[],"payload":{"tag":"li","lines":"118,119"}},{"content":"Quadras e centros esportivos","children":[],"payload":{"tag":"li","lines":"119,120"}},{"content":"Ruas e bairros","children":[],"payload":{"tag":"li","lines":"120,122"}}],"payload":{"tag":"h3","lines":"115,116"}}],"payload":{"tag":"h2","lines":"102,103"}},{"content":"🔬 Indicadores de Maturação Biológica","children":[{"content":"Maturação sexual – Critérios de Tanner (1962)","children":[{"content":"5 estágios: pré-puberal (E1) → adulto (E5)","children":[],"payload":{"tag":"li","lines":"126,127"}},{"content":"Observa pilosidade pubiana (meninos e meninas) + mamas (meninas) + genitália (meninos)","children":[],"payload":{"tag":"li","lines":"127,129"}}],"payload":{"tag":"h3","lines":"125,126"}},{"content":"Maturação óssea","children":[{"content":"Ossificação da cartilagem de crescimento","children":[],"payload":{"tag":"li","lines":"130,131"}},{"content":"Avaliação por raio-X da mão/punho esquerdo → método Greulich-Pyle","children":[],"payload":{"tag":"li","lines":"131,133"}}],"payload":{"tag":"h3","lines":"129,130"}},{"content":"Maturação dental","children":[{"content":"Erupção de dentes temporários e permanentes","children":[],"payload":{"tag":"li","lines":"134,136"}}],"payload":{"tag":"h3","lines":"133,134"}},{"content":"Maturação morfológica","children":[{"content":"Medidas antropométricas (mais simples e menos invasivas)","children":[],"payload":{"tag":"li","lines":"137,138"}},{"content":"Condições dos indicadores (Guedes; Guedes, 2006): aumento contínuo, independência de tamanho, estágio final igual para todos","children":[],"payload":{"tag":"li","lines":"138,139"}}],"payload":{"tag":"h3","lines":"136,137"}}],"payload":{"tag":"h2","lines":"124,125"}}],"payload":{"tag":"h1","lines":"0,1"}},null)
